"""Shared loading / utils for T2-RD. Snapshot-first, nflreadpy fallback (sample only)."""
import os, glob, hashlib
import numpy as np
import pandas as pd

SEED = 20260913
SNAP_DIR = os.path.expanduser("~/workspace/gse-discovery/data_snapshot_20260913")
WORK = os.path.expanduser("~/workspace/gse-discovery/phase6/t2-rd")

WANT_COLS = [
    "season", "game_id", "week", "posteam", "defteam", "qtr", "down",
    "ydstogo", "yardline_100", "score_differential", "game_seconds_remaining",
    "epa", "first_down", "touchdown", "play_type", "pass", "rush",
    "shotgun", "no_huddle", "play_action", "qb_kneel", "qb_spike",
    "sack", "roof", "surface", "temp", "wind",
]

def snapshot_present():
    m = os.path.join(SNAP_DIR, "MANIFEST.md")
    return os.path.exists(m)

def _from_snapshot(seasons):
    files = sorted(glob.glob(os.path.join(SNAP_DIR, "pbp_*.parquet")))
    if not files:
        raise FileNotFoundError("no pbp parquet in snapshot dir")
    import pyarrow.parquet as pq
    frames = []
    for f in files:
        avail = set(pq.read_schema(f).names)
        cols = [c for c in WANT_COLS if c in avail]
        frames.append(pd.read_parquet(f, columns=cols))
    df = pd.concat(frames, ignore_index=True)
    # category dtypes for team cols to keep memory lean
    for c in ("posteam", "defteam", "roof", "surface"):
        if c in df.columns:
            df[c] = df[c].astype("category")
    return df[df["season"].isin(seasons)].reset_index(drop=True)

def _from_nflreadpy(seasons):
    import nflreadpy
    df = nflreadpy.load_pbp(seasons=list(seasons))
    try:
        import polars as pl
        if isinstance(df, pl.DataFrame):
            df = df.to_pandas()
    except ImportError:
        pass
    cols = [c for c in WANT_COLS if c in df.columns]
    return df[cols].copy()

def load_pbp(seasons):
    seasons = list(seasons)
    if snapshot_present():
        return _from_snapshot(seasons), "snapshot"
    print("WARNING: snapshot absent - using live nflreadpy (SAMPLE ONLY, unversioned)")
    return _from_nflreadpy(seasons), "nflreadpy-live"

def base_plays(df):
    """Regular scrimmage plays: drop kneels, spikes, non-team rows."""
    d = df.copy()
    for c in ("qb_kneel", "qb_spike"):
        if c in d.columns:
            d = d[d[c].fillna(0).astype(int) == 0]
    d = d[d["posteam"].notna()]
    if "play_type" in d.columns:
        d = d[~d["play_type"].isin(["no_play"])]
    return d.reset_index(drop=True)

def add_derived(d):
    d = d.copy()
    if "pass" not in d.columns and "play_type" in d.columns:
        d["pass"] = (d["play_type"] == "pass").astype(int)
    if "rush" not in d.columns and "play_type" in d.columns:
        d["rush"] = (d["play_type"] == "run").astype(int)
    for c in ("pass", "rush", "shotgun", "no_huddle", "first_down", "touchdown"):
        if c in d.columns:
            d[c] = d[c].fillna(0).astype(int)
    if "play_action" in d.columns:
        d["play_action"] = d["play_action"].fillna(0).astype(int)
    d["conversion"] = ((d["first_down"] == 1) | (d["touchdown"] == 1)).astype(int)
    if "play_type" in d.columns:
        d["fg_attempt"] = (d["play_type"] == "field_goal").astype(int)
    else:
        d["fg_attempt"] = 0
    return d

def code_hash(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()[:12]

