"""T8 symbolic-regression engine: custom numpy tree-GP with islands + migration.

Why custom (see PREREG.md §5): the T8 design IS the overfitting controls
(islands+migration, parsimony sweeps, stability hooks); gplearn has no native
support for them. Engine is intentionally small, memory-flat, deterministic
given a seed.

Program representation: nested tuples.
  ('f', name, child, ...) | ('x', feature_index) | ('c', float)

Evaluation is vectorized over rows: each program compiles to a closure over
feature arrays, called once per generation-batch.
"""

import math
import numpy as np

# ---------------------------------------------------------------- functions
def _pdiv(a, b):
    return np.where(np.abs(b) > 1e-6, a / np.where(np.abs(b) > 1e-6, b, 1.0),
                    np.sign(a) * np.abs(a))

def _psqrt(a):
    return np.sqrt(np.abs(a))

def _plog(a):
    return np.log1p(np.abs(a))

def _square(a):
    return a * a

def _neg(a):
    return -a

FUNCS = {
    'add': (2, lambda a, b: a + b, True),
    'sub': (2, lambda a, b: a - b, False),
    'mul': (2, lambda a, b: a * b, True),
    'pdiv': (2, _pdiv, False),
    'psqrt': (1, _psqrt, False),
    'square': (1, _square, False),
    'plog': (1, _plog, False),
    'min': (2, np.minimum, True),
    'max': (2, np.maximum, True),
    'neg': (1, _neg, False),
    'sin': (1, np.sin, False),
}
FUNC_NAMES = list(FUNCS.keys())
COMMUTATIVE = {n for n, (_, _, c) in FUNCS.items() if c}

# ------------------------------------------------------------------ trees

def count_nodes(t):
    if t[0] in ('x', 'c'):
        return 1
    return 1 + sum(count_nodes(ch) for ch in t[2:])


def tree_depth(t):
    if t[0] in ('x', 'c'):
        return 1
    return 1 + max(tree_depth(ch) for ch in t[2:])


def compile_prog(t, Xcols):
    """Return a closure f() -> np.ndarray evaluated on feature column list."""
    kind = t[0]
    if kind == 'x':
        col = Xcols[t[1]]
        return lambda: col
    if kind == 'c':
        v = float(t[1])
        return lambda: np.full(Xcols[0].shape, v)
    _, fn, _ = FUNCS[t[1]]
    child_fns = [compile_prog(ch, Xcols) for ch in t[2:]]
    if len(child_fns) == 1:
        g = child_fns[0]
        return lambda: fn(g())
    g1, g2 = child_fns
    return lambda: fn(g1(), g2())


def _lin_scale(pred, y):
    """Least-squares affine fit a*pred + b on (pred, y). Returns (a, b, r2)."""
    p = pred - pred.mean()
    denom = float((p ** 2).sum())
    if denom < 1e-12 or not np.isfinite(denom):
        return 0.0, float(y.mean()), 0.0
    a = float((p * (y - y.mean())).sum() / denom)
    b = float(y.mean() - a * pred.mean())
    resid = y - (a * pred + b)
    ss_res = float((resid ** 2).sum())
    ss_tot = float(((y - y.mean()) ** 2).sum())
    r2 = 1.0 - ss_res / ss_tot if ss_tot > 1e-12 else 0.0
    return a, b, r2


def evaluate(t, Xcols, y, max_nodes):
    """Fitness = train R² (with affine scaling) − parsimony penalty."""
    try:
        with np.errstate(all='ignore'):
            pred = compile_prog(t, Xcols)()
        if not np.all(np.isfinite(pred)):
            return -np.inf, 0.0, 0.0, 0.0
        n = count_nodes(t)
        a, b, r2 = _lin_scale(pred, y)
        if not np.isfinite(r2):
            return -np.inf, 0.0, 0.0, 0.0
        return r2, a, b, n
    except Exception:
        return -np.inf, 0.0, 0.0, 0.0


# ------------------------------------------------------------- generation

def rand_tree(rng, n_features, max_depth, method):
    if max_depth <= 1 or (method == 'grow' and rng.random() < 0.4):
        # terminal
        if rng.random() < 0.7:
            return ('x', int(rng.integers(0, n_features)))
        return ('c', float(rng.uniform(-2.0, 2.0)))
    name = FUNC_NAMES[int(rng.integers(0, len(FUNC_NAMES)))]
    arity, _, _ = FUNCS[name]
    kids = tuple(rand_tree(rng, n_features, max_depth - 1, method)
                 for _ in range(arity))
    return ('f', name) + kids


def _subtree_paths(t, path=()):
    paths = [path]
    if t[0] == 'f':
        for i, ch in enumerate(t[2:]):
            paths += _subtree_paths(ch, path + (i,))
    return paths


def _get(t, path):
    for i in path:
        t = t[2 + i]
    return t


def _set(t, path, sub):
    if not path:
        return sub
    kind = t[0]
    kids = list(t[2:])
    kids[path[0]] = _set(kids[path[0]], path[1:], sub)
    return ('f', t[1]) + tuple(kids)


def crossover(rng, p1, p2, max_depth, n_features):
    q1 = _subtree_paths(p1)
    q2 = _subtree_paths(p2)
    s1 = _get(p1, q1[int(rng.integers(0, len(q1)))])
    s2 = _get(p2, q2[int(rng.integers(0, len(q2)))])
    c1 = _set(p1, q1[int(rng.integers(0, len(q1)))], s2)
    if tree_depth(c1) > max_depth or count_nodes(c1) > 63:
        return p1
    return c1


def subtree_mutation(rng, p, max_depth, n_features):
    q = _subtree_paths(p)
    path = q[int(rng.integers(0, len(q)))]
    depth_here = len(path)
    new_sub = rand_tree(rng, n_features, max(1, max_depth - depth_here), 'grow')
    c = _set(p, path, new_sub)
    if tree_depth(c) > max_depth or count_nodes(c) > 63:
        return p
    return c


def point_mutation(rng, p, n_features):
    q = _subtree_paths(p)
    path = q[int(rng.integers(0, len(q)))]
    node = _get(p, path)
    if node[0] == 'f':
        arity = FUNCS[node[1]][0]
        cands = [n for n in FUNC_NAMES if FUNCS[n][0] == arity and n != node[1]]
        if not cands:
            return p
        new = ('f', cands[int(rng.integers(0, len(cands)))]) + node[2:]
        return _set(p, path, new)
    if node[0] == 'x':
        return _set(p, path, ('x', int(rng.integers(0, n_features))))
    return _set(p, path, ('c', float(node[1] + rng.normal(0, 0.5))))


# ------------------------------------------------------------- canonical

def _fmt_const(v):
    if v == 0:
        return '0'
    return '%.3g' % v


def canonical(t, skeleton=False):
    """Canonical string; skeleton=True replaces constants with 'C'."""
    kind = t[0]
    if kind == 'x':
        return 'x%d' % t[1]
    if kind == 'c':
        return 'C' if skeleton else _fmt_const(t[1])
    name = t[1]
    kids = [canonical(ch, skeleton) for ch in t[2:]]
    if name in COMMUTATIVE:
        kids = sorted(kids)
    return '%s(%s)' % (name, ','.join(kids))


def to_infix(t, feat_names):
    kind = t[0]
    if kind == 'x':
        return feat_names[t[1]]
    if kind == 'c':
        return _fmt_const(t[1])
    name = t[1]
    kids = [to_infix(ch, feat_names) for ch in t[2:]]
    if name == 'add':
        return '(%s + %s)' % (kids[0], kids[1])
    if name == 'sub':
        return '(%s - %s)' % (kids[0], kids[1])
    if name == 'mul':
        return '(%s * %s)' % (kids[0], kids[1])
    if name == 'pdiv':
        return '(%s /p %s)' % (kids[0], kids[1])
    if name == 'neg':
        return '(-%s)' % kids[0]
    return '%s(%s)' % (name, ', '.join(kids))


# ------------------------------------------------------------------ run

def run_islands(Xcols_tr, y_tr, Xcols_va, y_va, seed, lam,
                n_islands=4, pop_size=400, generations=60, max_depth=5,
                max_nodes=31, mig_every=10, n_migrants=5, log=None,
                val_track_k=25, val_sub=None):
    """Evolve; select winner on validation. Returns dict with winner + stats.

    Efficiency: each program evaluated ONCE per generation (train fitness).
    Validation R² computed only for top-`val_track_k` by train fitness, on a
    `val_sub` subsample during evolution; the final winner is re-scored on the
    FULL validation set by the caller (pipeline).
    """
    rng = np.random.default_rng(seed)
    n_features = len(Xcols_tr)
    if val_sub is None:
        val_sub = np.arange(len(y_va))
    Xv = [c[val_sub] for c in Xcols_va]
    yv = y_va[val_sub]
    islands = []
    for _ in range(n_islands):
        pop = [rand_tree(rng, n_features, max_depth,
                         'full' if i % 2 == 0 else 'grow')
               for i in range(pop_size)]
        islands.append(pop)

    def prog_fitness(t):
        """Single evaluation per program: returns (fitness, r2, a, b, nodes, pred_fn)."""
        r2, a, b, n = evaluate(t, Xcols_tr, y_tr, max_nodes)
        if r2 == -np.inf:
            return None
        return (r2 - lam * (n / max_nodes), r2, a, b, n)

    def val_r2_of(t, a, b):
        try:
            with np.errstate(all='ignore'):
                pred = compile_prog(t, Xv)()
            if not np.all(np.isfinite(pred)):
                return -np.inf
            resid = yv - (a * pred + b)
            ss_res = float((resid ** 2).sum())
            ss_tot = float(((yv - yv.mean()) ** 2).sum())
            return 1.0 - ss_res / ss_tot if ss_tot > 1e-12 else -np.inf
        except Exception:
            return -np.inf

    def tournament_id(fits, k=5):
        idx = rng.integers(0, len(fits), size=k)
        best = idx[0]
        for j in idx[1:]:
            if fits[j] > fits[best]:
                best = j
        return best

    best_overall = None  # (val_r2, tree, a, b, train_r2, nodes)
    for gen in range(generations):
        isl_data = []  # per island: (pop, fits_list, info_list)
        for isl in range(n_islands):
            pop = islands[isl]
            scored = [prog_fitness(t) for t in pop]
            fits = np.array([s[0] if s else -np.inf for s in scored])
            isl_data.append((pop, fits, scored))
            # validation tracking on top-k only
            order = np.argsort(-np.where(np.isfinite(fits), fits, -1e18))
            for i in order[:val_track_k]:
                s = scored[i]
                if s is None:
                    continue
                _, tr_r2, a, b, n = s
                vr = val_r2_of(pop[i], a, b)
                if best_overall is None or vr > best_overall[0]:
                    best_overall = (vr, pop[i], a, b, tr_r2, n)
        # breed next generation
        for isl in range(n_islands):
            pop, fits, scored = isl_data[isl]
            order = np.argsort(-np.where(np.isfinite(fits), fits, -1e18))
            new_pop = [pop[i] for i in order[:2]]
            while len(new_pop) < pop_size:
                r = rng.random()
                p1 = pop[tournament_id(fits)]
                if r < 0.70:
                    p2 = pop[tournament_id(fits)]
                    child = crossover(rng, p1, p2, max_depth, n_features)
                elif r < 0.90:
                    child = subtree_mutation(rng, p1, max_depth, n_features)
                else:
                    child = point_mutation(rng, p1, n_features)
                new_pop.append(child)
            islands[isl] = new_pop
        # migration (reuse stored fitness)
        if (gen + 1) % mig_every == 0 and n_islands > 1:
            tops = []
            for isl in range(n_islands):
                pop, fits, _ = isl_data[isl]
                order = np.argsort(-np.where(np.isfinite(fits), fits, -1e18))
                tops.append([pop[i] for i in order[:n_migrants]])
            for isl in range(n_islands):
                src = tops[(isl - 1) % n_islands]
                pop, fits, _ = isl_data[isl]
                order = np.argsort(np.where(np.isfinite(fits), fits, 1e18))
                for k in range(n_migrants):
                    islands[isl][order[k]] = src[k % len(src)]
        if log and (gen + 1) % 20 == 0:
            log('gen %d/%d best_val_r2=%.4f' % (gen + 1, generations, best_overall[0]))
    vr, t, a, b, tr_r2, n = best_overall
    return {'tree': t, 'a': a, 'b': b, 'train_r2': tr_r2,
            'val_r2': vr, 'nodes': n,
            'skeleton': canonical(t, skeleton=True)}

